-- Create "tenant_inventory_configs" table
CREATE TABLE "tenant_inventory_configs" ("id" uuid NOT NULL, "tenant_id" uuid NOT NULL, "low_stock_threshold_pct" double precision NOT NULL DEFAULT 20, "critical_stock_threshold_pct" double precision NOT NULL DEFAULT 5, "default_reorder_level" bigint NOT NULL DEFAULT 10, "expiry_warning_days" bigint NOT NULL DEFAULT 30, "enable_low_stock_notifications" boolean NOT NULL DEFAULT true, "enable_expiry_notifications" boolean NOT NULL DEFAULT true, "notification_email" character varying NULL, "default_warehouse_id" character varying NULL, "enable_lot_tracking" boolean NOT NULL DEFAULT false, "enable_expiry_tracking" boolean NOT NULL DEFAULT false, "purchase_order_approval_required" boolean NOT NULL DEFAULT false, "auto_adjust_on_transfer" boolean NOT NULL DEFAULT true, "lots_module_enabled" boolean NOT NULL DEFAULT false, "recipes_module_enabled" boolean NOT NULL DEFAULT false, "purchase_orders_enabled" boolean NOT NULL DEFAULT true, "supplier_management_enabled" boolean NOT NULL DEFAULT true, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "tenantinventoryconfig_tenant_id" to table: "tenant_inventory_configs"
CREATE UNIQUE INDEX "tenantinventoryconfig_tenant_id" ON "tenant_inventory_configs" ("tenant_id");
